import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {tmpdir} from 'node:os';
import {WebSocket} from 'ws';
import {createRequire} from 'node:module';
import {newGame,transfer} from '../engine.mjs';
import {reduceAction} from '../multiplayer/actions.mjs';
import {manaAbilities} from '../mana.mjs';
import {projectGame,compactView,expandView,diff,applyPatch,digest} from '../multiplayer/protocol.mjs';
